-- shift_staff_march2025.sql
-- 7 days: 2025-03-01 to 2025-03-07 | 13 departments × 21 shifts = 273
-- 273/273 shifts staffed
-- Requires new_staff_for_march.sql first (staff_ids 283-291).
-- ALL residents (66-82) excluded — no supervisor constraint triggered.
-- Global monthly limits enforced. No multi-dept doctor overlap.
-- EXTRACT(YEAR)=2025 prevents cross-match with May 2026 shifts.
-- NOT EXISTS prevents duplicate key on re-run.


